  assert.equal(result.ok, false);
  assert.equal(result.error, 'CUSTOMER_NOT_FOUND');
});

test('mergeCustomers does not mutate original arrays', () => {
  const customers = [
    { id: 'C-001', name: 'Northwind Studio', email: 'accounts@northwind.example', country: 'NL', tier: 'gold' },
    { id: 'C-002', name: 'Blue Fern Bakery', email: 'hello@bluefern.example', country: 'NL', tier: 'standard' },
  ];
  const invoices = [
    { customerId: 'C-002', number: 'INV-2026-0001', status: 'issued', lines: [] },
  ];
